const $=id=>document.getElementById(id),token=document.body.dataset.token;
const endpoint=(path,params={})=>{const u=new URL(path,location.href);u.searchParams.set('access_token',token);for(const [k,v] of Object.entries(params))u.searchParams.set(k,v);return u.href;};
