const validCode=value=>/^[1-9]\d{8}$/.test(value)||/^[A-F0-9]{24}$/.test(value);
const formatted=value=>/^\d{9}$/.test(value)?value.replace(/(\d{3})(?=\d)/g,'$1 '):value;
