function notice(message){$('notice').textContent=message;$('notice').hidden=!message;}
async function request(path,data,params){const r=await fetch(endpoint(path,params),{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store',signal:AbortSignal.timeout(path.includes('activate')?20000:6000)});if(!r.ok)throw Error((await r.text()).slice(0,300));return r.json();}
function tab(name){for(const pane of document.querySelectorAll('.pane'))pane.hidden=pane.id!=='pane-'+name;for(const button of document.querySelectorAll('nav [data-tab]'))button.classList.toggle('selected',button.dataset.tab===name);$('pageTitle').textContent=({remote:'远程控制',meeting:'会议',devices:'设备列表',files:'文件传输',settings:'设置'})[name];if(name==='devices')loadDevices();}
for(const button of document.querySelectorAll('[data-tab]'))button.onclick=()=>tab(button.dataset.tab);
$('homeBrand').onclick=event=>{event.preventDefault();tab('remote');};
