function updateLocal(s){if(local&&(s.pinRevision||0)<(local.pinRevision||0))s={...s,pin:local.pin,pinSynced:local.pinSynced,pinRevision:local.pinRevision};local=s;$('sidebarName').textContent=s.name;$('localName').textContent=s.name;$('localCode').textContent=s.code?formatted(s.code):'正在分配';$('localPIN').textContent=revealPIN?s.pin:'••••••';$('receiving').checked=s.receiving;$('filePermission').checked=s.files;$('receiveDirectory').textContent=s.fileDirectory;$('licenseLabel').textContent='设备授权：'+s.activeUntil;$('serverDot').classList.toggle('online',s.online);$('serverState').textContent=s.online?'服务器已连接':'连接服务器中';$('localState').textContent=!s.receiving?'已暂停接入':s.connected?'连接中':!s.online?'正在连接':s.active?'在线待连接':'等待激活';$('localState').className='badge '+(!s.receiving?'neutral':s.connected||s.online&&s.active?'good':'warning');$('copyCode').disabled=!s.code;$('copyBoth').disabled=!s.code;if(s.code)statuses.set(s.code,{online:s.online,connected:s.connected,active:s.active,ready:s.active&&s.online&&s.receiving&&!s.connected});updateMeeting(s);updateBadges();}
async function refreshLocal(){const generation=pinRequest;try{const value=await request('/api/local/status');if(generation===pinRequest&&!pinRotating)updateLocal(value);if(pendingPIN&&value.pin===pendingPIN&&value.pinSynced){pendingPIN='';notice('PIN 已更换并同步后台，旧 PIN 已失效');}}catch(_){}setTimeout(refreshLocal,2000);}
